Y = (15,0);
Z = (0,5);
draw(X--Y--Z--X);
draw(rightanglemark(Y,X,Z,23));
label("$X$",X,SW);
label("$Y$",Y,SE);
label("$Z$",Z,N);
//label("$100$",(Y+Z)/2,NE);
label("$k$",(Z)/2,W);
label("$3k$",Y/2,S);
[/asy]

